const raw = $json["output"][0]["content"][0]["text"];

// Remove ```json ``` wrapper
const cleaned = raw.replace(/```json|```/g, '').trim();

// Extract JSON safely
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);

if (!jsonMatch) {
  throw new Error("No valid JSON found in AI response");
}

return [
  {
    json: JSON.parse(jsonMatch[0])
  }
];

