// Get the current item
const item = $json;
const tallyData = $('Tally Trigger').first().json;

// --- NEW: PRIORITY LOGIC ---
const score = item.evaluation?.score || 0;
let priorityName = "Low";
let nativePriority = 4; // Native ClickUp: 1=Urgent, 2=High, 3=Normal, 4=Low
let customPriorityIndex = 3; // Custom Dropdown index (0=Urgent, 1=High, etc.)

if (score >= 90) {
  priorityName = "Urgent";
  nativePriority = 1;
  customPriorityIndex = 0;
} else if (score >= 80) {
  priorityName = "High";
  nativePriority = 2;
  customPriorityIndex = 1;
} else if (score >= 75) {
  priorityName = "Normal";
  nativePriority = 3;
  customPriorityIndex = 2;
}

// 1. Build the cleanly formatted Markdown Description
const missingSkills = item.evaluation?.missing_skills?.length > 0 
  ? "- " + item.evaluation.missing_skills.join('\n- ') 
  : "*None*";

const taskDescription = `#### Evaluation Summary
**Score:** ${item.evaluation?.score || 0}/100
**Candidate Level:** ${item.evaluation?.tier || ""}
**Experience Status:** ${item.evaluation?.experience_status || ""}
#### Missing Required Skills:
${missingSkills}
#### Applicant Details
**Email:** ${item.Email || ""}
**Phone:** ${item['Phone Number'] || ""}
**Date Applied:** ${item['Date Applied'] || ""}
**Resume URL:** ${tallyData.question_zza50M?.value || ""}`;

// --- MAP DROPDOWNS TO INDICES ---
// Position Dropdown (0 is the first option in ClickUp, 1 is the second, etc.)
const positionIndexMap = {
  "Software Engineer": 0,
  "AI Developer": 1,
  "AI Engineer": 2,
  "AI Automation Specialist": 3 
};

// Candidate Level Dropdown 
const tierIndexMap = {
  "Strong": 0,
  "Moderate": 1,
  "Weak": 2
};

// --- BUILD THE PAYLOAD ---
// We filter out any empty values at the very end so ClickUp doesn't crash on blank values.
const clickUpCustomFields = [
  { "id": "cb5ce372-e476-4930-a208-0187a7b55785", "value": item['First Name'] },   // First Name Field
  { "id": "eb958b5e-73d5-42e8-bdd5-865734188461", "value": item['Last Name'] },    // Last Name Field
  { "id": "de8635f1-8b3c-40c8-b41b-dd5362b88817", "value": positionIndexMap[item.Position] },  // Position Field
  { "id": "a7c619c7-4edb-4daa-8268-5905e3eb7db7", "value": item.Email },    // Email Field
  { "id": "cd1c8ae0-82ef-4732-81d1-52f92d91875e", "value": item['Phone Number'] },   // Phone Number Field
  { "id": "388e2c53-20a3-403a-a9aa-4a64caf3f223", "value": parseInt(item.evaluation?.score) },   // Score Field
  { "id": "afc07cf7-996f-4db1-8253-b641df2e8c6b", "value": item.evaluation?.qualification },      // Qualification Field
  { "id": "ead7a1aa-bbbf-4dc0-8d5c-4469f5744600", "value": item.evaluation?.overview },    // Overview Field
  { "id": "39291c43-4480-4bf2-b8f3-ba0c311c175a", "value": tierIndexMap[item.evaluation?.tier] },    // Candidate Level Field
  { "id": "f59cb836-9210-49bd-b181-1ff3975fae29", "value": item.years_experience !== undefined ? item.years_experience + " years" : undefined },   // Experience Field  
  { "id": "e930b843-64be-4e1a-a7f4-97ff99618ab3", "value": tallyData.question_zza50M?.value },   // Resume Link Field
  { "id": "0f980d8d-461d-4dcf-a3eb-b1221e432013", "value": tallyData.createdAt ? new Date(tallyData.createdAt).getTime() : undefined },    // Date Applied Field
  { "id": "d85fd3b7-28b2-4d64-b6df-5a45d0a22227", "value": item['Possible Start Date'] ? new Date(item['Possible Start Date']).getTime() : undefined },   // Possible Start Date Field
  { "id": "68a3ba77-06ce-49dc-88df-b7a3b91c7a60", "value": item['Preferred Interview Date'] ? new Date(item['Preferred Interview Date']).getTime() : undefined } // Preferred Interview Date Field

].filter(field => field.value !== undefined && field.value !== null && field.value !== "" && !Number.isNaN(field.value));

// Attach the payload to the outgoing JSON
return {
  json: {
    ...item,
    calculatedPriorityStr: priorityName,
    calculatedPriorityNative: nativePriority, // 1, 2, 3, or 4
    clickUpPayload: JSON.stringify(clickUpCustomFields),
    taskDescription: taskDescription
  }
};

const task = $json;

// Helper function to format ClickUp timestamps into readable dates (for Sheets)
function formatClickUpDate(fieldId) {
  const field = task.custom_fields.find(f => f.id === fieldId);
  if (field && field.value) {
    const date = new Date(parseInt(field.value));
    return date.toLocaleDateString('en-US', {
      month: 'long',
      day: '2-digit',
      year: 'numeric'
    });
  }
  return null;
}

// 1. Extract Email
const emailField = task.custom_fields.find(f => f.id === 'a7c619c7-4edb-4daa-8268-5905e3eb7db7');
const email = emailField ? emailField.value : null;

// 2. Extract Position Index for Sheet Mapping
const posField = task.custom_fields.find(f => f.id === 'de8635f1-8b3c-40c8-b41b-dd5362b88817');
const posIndex = posField && posField.value !== undefined ? parseInt(posField.value) : null;

const sheetMap = {
  0: "1864540035", // Software Engineer
  1: "1893627576", // AI Developer
  2: "1310853920", // AI Engineer
  3: "0"           // AI Automation Specialist
};
const sheetId = sheetMap[posIndex] || "0";

// 3. Extract and Format Dates for Sheets
const dateApplied = formatClickUpDate('0f980d8d-461d-4dcf-a3eb-b1221e432013');
const interviewDate = formatClickUpDate('68a3ba77-06ce-49dc-88df-b7a3b91c7a60');
const startDate = formatClickUpDate('d85fd3b7-28b2-4d64-b6df-5a45d0a22227');

// 4. Extract Native ClickUp Dates for Google Calendar
const rawStartDate = task.start_date ? parseInt(task.start_date) : null;
const rawDueDate = task.due_date ? parseInt(task.due_date) : null;

// Convert to ISO 8601 format required by Google Calendar
const calendarStartTime = rawStartDate ? new Date(rawStartDate).toISOString() : null;

// Fallback: If no Due Date is set, default the interview to 1 hour (60 * 60 * 1000 ms)
const calendarEndTime = rawDueDate 
  ? new Date(rawDueDate).toISOString() 
  : (rawStartDate ? new Date(rawStartDate + 3600000).toISOString() : null);

// 5. Status Formatting
const newStatus = task.status.status;
const formattedStatus = newStatus.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

return {
  json: {
    ...task,
    extractedEmail: email,
    targetSheetId: sheetId,
    formattedStatus: formattedStatus,
    dateApplied: dateApplied,
    interviewDate: interviewDate, 
    startDate: startDate,
    calendarStartTime: calendarStartTime,
    calendarEndTime: calendarEndTime
  }
};

// Retrieve the original candidate data from the first node
const candidateData = $('1. Store Job Descriptions').first().json;

// Extract the AI's JSON string
const aiResponse = $json.output[0].content[0].text;
const cleaned = aiResponse.replace(/```json|```/g, '').trim();
const atsEvaluation = JSON.parse(cleaned);

// Rebuild the object exactly how ClickUp, Sheets, and Emails expect it
return {
  json: {
    ...candidateData,
    evaluation: {
      score: atsEvaluation.score,
      tier: atsEvaluation.tier,
      qualification: atsEvaluation.qualification,
      overview: atsEvaluation.overview,
      found_skills: atsEvaluation.found_skills,
      missing_skills: atsEvaluation.missing_skills,
      experience_status: atsEvaluation.experience_status,
      upload_folder_id: candidateData.upload_folder_id,
      upload_sheet_id: candidateData.upload_sheet_id
    }
  }
};
